command:
"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command '$materialPath = Join-Path (Get-Location).Path '"'materials/第三章.md'
"'$materialLines = @(Get-Content -LiteralPath $materialPath -Encoding UTF8 -ErrorAction Stop)
foreach ($lineNumber in @(8, 42)) {
    if ($materialLines.Count -lt $lineNumber) { throw "Requested line $lineNumber is missing; total lines: $($materialLines.Count)" }
    Write-Output ('"'materials/第三章.md:{0}: {1}' -f "'$lineNumber, $materialLines[$lineNumber - 1])
}'

